// spec: specs/stale-chunk-reload.md (1.1, 1.2) · кейсы: .qa/tests/stale-chunk-reload/STALE-CHUNK-01, 02
// seed: tests/seed.spec.ts (гость) · прод, только просмотр; Chromium (десктоп и Pixel 7).
import { test, expect } from '@playwright/test';
import {
  CALC_H1, DEVICES, LOAD, LOADING_TEXT, ChunkMode,
  breakCalculatorChunk, clickCalculatorLink, openHome, prepare, ss, trackDocumentNavigations,
} from './stale-chunk.helpers';

test.use({ serviceWorkers: 'block' });

const CASES: { mode: ChunkMode; title: string }[] = [
  { mode: '404-once', title: 'чанк калькулятора 404 один раз' },
  { mode: 'html-once', title: 'вместо чанка калькулятора 200 text/html' },
];

test.describe('устаревший чанк после деплоя — автозагрузка новой версии', () => {
  for (const device of DEVICES) {
    for (const c of CASES) {
      test(`${c.title} → «${LOADING_TEXT}», 1 перезагрузка, калькулятор открыт #4f5e3a ${device} @prod-safe`, async ({ page, context, browserName }) => {
        test.skip(browserName !== 'chromium', 'только Chromium (по сценарию тикета)');
        await prepare(context);
        const chunk = await breakCalculatorChunk(page, c.mode);
        await openHome(page);
        expect(chunk.hits, 'чанк калькулятора не загружался до клика').toBe(0);

        const docs = trackDocumentNavigations(page);
        await clickCalculatorLink(page);

        await expect(page.getByRole('heading', { level: 1, name: CALC_H1 }), 'калькулятор открылся').toBeVisible(LOAD);
        await expect(page).toHaveURL(/\/calculator$/);
        expect(chunk.hits, 'перехват чанка сработал, после перезагрузки чанк запрошен снова').toBeGreaterThanOrEqual(2);
        expect(docs, 'ровно одна перезагрузка документа — /calculator').toHaveLength(1);
        expect(new URL(docs[0]).pathname).toBe('/calculator');
        expect(await ss(page, 'qa:saw-loading'), `текст «${LOADING_TEXT}» был показан`).toContain('/calculator;');
        expect(await ss(page, 'qa:saw-error'), '«משהו השתבש» не показывался').toBeNull();
      });
    }
  }
});
